@push('scripts')<script>(()=>{document.querySelectorAll('.tenant-quote-form').forEach(form=>{const type=form.querySelector('[data-package-type]'),dims=form.querySelector('[data-dimensions]'),requests=new Map();const sync=()=>{const box=type?.value==='caja';dims.hidden=!box;dims.querySelectorAll('input').forEach(i=>i.required=box)};const reset=(input,message='Captura primero el CP')=>{const side=input.dataset.postal,select=form.querySelector(`[data-settlement="${side}"]`),location=form.querySelector(`[data-location="${side}"]`),wrap=form.querySelector(`[data-settlement-wrap="${side}"]`);requests.get(side)?.abort();requests.delete(side);delete input.dataset.loadedPostal;select.replaceChildren(new Option(message,''));select.disabled=true;location.textContent='';wrap.dataset.state='idle'};const lookup=async input=>{const postal=input.value.trim(),side=input.dataset.postal;if(!/^\d{5}$/.test(postal)){reset(input);return}if(input.dataset.loadedPostal===postal)return;requests.get(side)?.abort();const controller=new AbortController();requests.set(side,controller);const select=form.querySelector(`[data-settlement="${side}"]`),location=form.querySelector(`[data-location="${side}"]`),wrap=form.querySelector(`[data-settlement-wrap="${side}"]`),selected=select.dataset.selected||'';wrap.dataset.state='loading';select.disabled=true;select.replaceChildren(new Option('Consultando colonias…',''));location.textContent='Consultando municipio y estado…';try{const response=await fetch(`/codigos-postales/${postal}`,{headers:{Accept:'application/json'},signal:controller.signal}),data=await response.json();if(!response.ok)throw new Error(data.message);const colonies=Array.isArray(data.colonias)?data.colonias:[];select.replaceChildren();if(colonies.length!==1)select.add(new Option('Selecciona una colonia',''));colonies.forEach(colony=>select.add(new Option(colony.nombre,colony.nombre)));if(colonies.length===1)select.value=colonies[0].nombre;else if(selected&&colonies.some(colony=>colony.nombre===selected))select.value=selected;select.disabled=colonies.length===0;select.required=true;location.textContent=[data.municipio,data.estado].filter(Boolean).join(', ');wrap.dataset.state='ready';input.dataset.loadedPostal=postal}catch(error){if(error.name==='AbortError')return;select.replaceChildren(new Option('No fue posible consultar colonias',''));select.disabled=true;location.textContent=error.message||'Intenta nuevamente';wrap.dataset.state='error';delete input.dataset.loadedPostal}};type?.addEventListener('change',sync);sync();form.querySelectorAll('[data-postal]').forEach(input=>{input.addEventListener('input',()=>{input.value=input.value.replace(/\D/g,'').slice(0,5);if(input.value.length===5)lookup(input);else reset(input)});input.addEventListener('blur',()=>lookup(input));if(/^\d{5}$/.test(input.value))lookup(input)})})})()</script>@endpush
@push('scripts')<script>(()=>{document.querySelectorAll('.tenant-quote-form').forEach(form=>{const type=form.querySelector('[data-package-type]'),weight=form.querySelector('[data-weight]'),dims=[...form.querySelectorAll('[data-dimension]')],note=form.querySelector('[data-billable]'),error=form.querySelector('[data-package-error]'),submit=form.querySelector('button[type=submit]');const validate=()=>{const box=type.value==='caja';weight.readOnly=!box;if(!box)weight.value=1;const values=Object.fromEntries(dims.map(input=>[input.dataset.dimension,Number(input.value||0)]));const invalid=box&&(Number(weight.value)>40||values.length>60||values.width>50||values.height>40);error.hidden=!invalid;error.textContent=invalid?'La caja excede los límites permitidos: 40 kg y 60 × 50 × 40 cm.':'';submit.disabled=invalid;if(box){const volumetric=values.length*values.width*values.height/5000;note.textContent=`Peso volumétrico: ${volumetric.toFixed(2)} kg · Peso facturable: ${Math.ceil(Math.max(Number(weight.value||0),volumetric))} kg`;}else note.textContent='Sobre: peso facturable de 1 kg.'};[type,weight,...dims].forEach(input=>input.addEventListener('input',validate));validate()})})()</script>@endpush
